import {size,normalizeAngle,polygonBounds} from './model.mjs';
export function localPoint(i,p){const [w,h]=size(i),a=-i.rotation*Math.PI/180,x=p.x-i.x-w/2,y=p.y-i.y-h/2;return {x:x*Math.cos(a)-y*Math.sin(a),y:x*Math.sin(a)+y*Math.cos(a)};}
export function resizeArea(i,handle,p){const q=localPoint(i,p),left=handle.includes('w')?Math.min(q.x,i.width/2-.5):-i.width/2,right=handle.includes('e')?Math.max(q.x,-i.width/2+.5):i.width/2,top=handle.includes('n')?Math.min(q.y,i.length/2-.5):-i.length/2,bottom=handle.includes('s')?Math.max(q.y,-i.length/2+.5):i.length/2;if(right-left>100||bottom-top>100)return {...i};const [w,h]=size(i),a=i.rotation*Math.PI/180,dx=(left+right)/2,dy=(top+bottom)/2,o={...i,width:right-left,length:bottom-top};const [nw,nh]=size(o);o.x=i.x+w/2+dx*Math.cos(a)-dy*Math.sin(a)-nw/2;o.y=i.y+h/2+dx*Math.sin(a)+dy*Math.cos(a)-nh/2;return o;}
export function areaFromWorldPoints(i,points){const local=points.map(([x,y])=>{const p=localPoint(i,{x,y});return [p.x,p.y];}),b=polygonBounds(local),[w,h]=size(i),a=i.rotation*Math.PI/180,dx=b.x+b.w/2,dy=b.y+b.h/2,o={...i,width:b.w,length:b.h,vertices:local.map(([x,y])=>[(x-b.x)/b.w,(y-b.y)/b.h])},[nw,nh]=size(o);o.x=i.x+w/2+dx*Math.cos(a)-dy*Math.sin(a)-nw/2;o.y=i.y+h/2+dx*Math.sin(a)+dy*Math.cos(a)-nh/2;return o;}
export function printTiles(region,cols,rows){return Array.from({length:cols*rows},(_,n)=>({x:region.x+n%cols*region.w/cols,y:region.y+Math.floor(n/cols)*region.h/rows,w:region.w/cols,h:region.h/rows}));}
